(function(){
  const chat=document.getElementById('chat');
  const flowScrim=document.getElementById('flowScrim');
  const flow=document.getElementById('flow');
  const flowNav=document.getElementById('flowNav');
  const flowTitle=document.getElementById('flowTitle');
  const flowBody=document.getElementById('flowBody');
  const flowPrimary=document.getElementById('flowPrimary');
  const pickScrim=document.getElementById('pickScrim');
  const picker=document.getElementById('picker');
  const pickTitle=document.getElementById('pickTitle');
  const pickList=document.getElementById('pickList');
  const pay=document.getElementById('pay');
  const payBody=document.getElementById('payBody');
  const payAmt=document.getElementById('payAmt');
  const paySpin=document.getElementById('paySpin');
  const toast=document.getElementById('toast');

  const TIME='11:59';
  const T_INTRO='7:25 PM';
  const T0='7:25 PM';
  const LOGO="data:image/png;base64,";
  const CHALLAN_IMG="data:image/jpeg;base64,";
  const BANNER="data:image/jpeg;base64,";
  const STAMP_TYPES=[
    {e:'🧵',t:'Non Judicial'},{e:'📑',t:'Special Adhesives'},{e:'📈',t:'Share Transfer'},
    {e:'🖋️',t:'Notary Stamps'},{e:'💱',t:'Foreign Bill'},{e:'🏛️',t:'Court Fee'},{e:'🪙',t:'Revenue Stamp'}
  ];
  const DENOMS=[10,20,100];
  const state={name:'',stampType:'',stampEmoji:'',denom:null,qty:''};

  function scrollDown(){chat.scrollTop=chat.scrollHeight;}
  function showToast(m){toast.textContent=m;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800);}

  function inBubble(html,ctas,time){
    time=time||TIME;
    const row=document.createElement('div');row.className='row in';
    let c='';if(ctas){ctas.forEach(x=>{c+='<div class="cta-row" data-act="'+x.act+'">'+x.label+'</div>';});}
    row.innerHTML='<div class="bubble"><div class="txt">'+html+'</div><div class="meta"><span class="time">'+time+'</span></div>'+c+'</div>';
    chat.appendChild(row);
    row.querySelectorAll('.cta-row').forEach(el=>el.addEventListener('click',()=>handleAct(el.dataset.act)));
    scrollDown();return row;
  }
  function rawBubble(inner){const row=document.createElement('div');row.className='row in';row.innerHTML='<div class="bubble">'+inner+'</div>';chat.appendChild(row);scrollDown();return row;}
  function outBubble(html,time){time=time||TIME;const row=document.createElement('div');row.className='row out';row.innerHTML='<div class="bubble"><div class="txt">'+html+'</div><div class="meta"><span class="time">'+time+'</span><span class="dtick">\u2713\u2713</span></div></div>';chat.appendChild(row);scrollDown();return row;}
  function botType(cb,d){const row=document.createElement('div');row.className='row in';row.innerHTML='<div class="bubble"><div class="typing"><span></span><span></span><span></span></div></div>';chat.appendChild(row);scrollDown();setTimeout(()=>{row.remove();cb();},d||650);}

  // ---------- start ----------
  function start(){
    chat.innerHTML='';
    Object.assign(state,{name:'',stampType:'',stampEmoji:'',denom:null,qty:''});
    const date=document.createElement('div');date.className='datepill';date.textContent='Today';
    const note=document.createElement('div');note.className='notice';note.innerHTML='🔒 This business uses a secure service from Meta to manage this chat. <a>Learn more</a>';
    chat.appendChild(date);chat.appendChild(note);

    // welcome (logo bubble + caption)
    rawBubble('<img class="welcome-logo" src="'+LOGO+'" alt="MeeSeva"><div class="txt">🙏 Namaskaaram! Welcome to <b>MeeSeva Telangana</b>.</div><div class="meta"><span class="time">'+TIME+'</span></div>');

    // services list
    inBubble(`MeeSeva Telangana is here to make citizen services simple and accessible. ✨

You can now get support for a wide range of citizen services, including:

📄  Certificate applications (Income, Birth, Death, etc.)
💡  Utility bill payments (Electricity, Water, Property Tax, etc.)
📊  Application status updates
🏛️  IGRS (Purchase of Stamps, Franking, Marriage Registration, etc.)

👉 How may I assist you today?
Please reply with the name of the service you'd like.

💬  For example: Income, Electricity Bill, Water Bill, Police Challan
🔎  To check a status, just type your application number.`);

    // user reply
    outBubble('Purchase of Stamps');

    // service card -> opens the stamps journey
    inBubble('<div class="svc-title">PAYMENT FOR PURCHASE OF STAMPS</div>',[{label:'Open Service!',act:'openService'}]);
  }

  function showStampCard(){
    const banner=`<img class="banner-img" src="${BANNER}" alt="Purchase of Registration Stamps"><div class="b-title">Purchase of Registration Stamps</div>Dear Customer,

🏷️ Buy your stamps, labels and adhesives in just a few steps!

✅ Quick &amp; Secure Payment
✅ Total Calculated For You

⚠️ Stamps are subject to availability at the SRO. If unavailable on your visit, the office will issue them at a later date and inform you.`;
    inBubble(banner,[{label:'Start Your Stamp Purchase',act:'openFlow'}]);
  }

  // ---------- flow ----------
  function openFlow(){flowScrim.classList.add('show');flow.classList.add('show');renderScreen(1);}
  function closeFlow(){flowScrim.classList.remove('show');flow.classList.remove('show');}

  let screen=1;
  function renderScreen(n){
    screen=n;
    if(n===1){
      flowTitle.textContent='Purchase of Stamps';
      flowNav.textContent='✕';flowNav.onclick=closeFlow;
      flowBody.innerHTML=`
        <img class="flow-hero" src="${BANNER}" alt="">
        <h2>Buy your registration stamps</h2>
        <div class="field" id="f-name">
          <label class="flabel">Full name of applicant</label>
          <input class="box" id="nameInput" placeholder="Enter name" value="${state.name.replace(/"/g,'&quot;')}">
        </div>
        <div class="field dropdown" id="f-type" data-pick="type">
          <label class="flabel">Stamp type</label>
          <div class="box ${state.stampType?'':'ph'}"><span id="typeVal">${state.stampType?(state.stampEmoji+' '+state.stampType):'Select stamp type'}</span><span class="chev">▾</span></div>
        </div>
        <div class="field dropdown" id="f-denom" data-pick="denom">
          <label class="flabel">Denomination (per stamp)</label>
          <div class="box ${state.denom?'':'ph'}"><span id="denomVal">${state.denom?('₹'+state.denom):'Select denomination'}</span><span class="chev">▾</span></div>
        </div>
        <div class="field" id="f-qty">
          <label class="flabel">Quantity</label>
          <input class="box" id="qtyInput" inputmode="numeric" placeholder="How many do you need?" value="${state.qty}">
        </div>
        <div class="totalhint" id="totalHint" style="display:none"></div>`;
      flowPrimary.textContent='Continue';
      flowPrimary.onclick=()=>{ if(!validate1())return; renderScreen(2); };
      wireScreen1();
      validate1();
    } else {
      flowTitle.textContent='Summary';
      flowNav.textContent='←';flowNav.onclick=()=>renderScreen(1);
      const face=(state.qty*state.denom);
      flowBody.innerHTML=`
        <h2>Summary of your selections</h2>
        <div class="sum-row"><div class="k">Applicant</div><div class="v">${state.name}</div></div>
        <div class="sum-row"><div class="k">Stamp type</div><div class="v">${state.stampEmoji} ${state.stampType}</div></div>
        <div class="sum-row"><div class="k">Denomination</div><div class="v">₹${state.denom.toFixed(2)}</div></div>
        <div class="sum-row"><div class="k">Quantity</div><div class="v">${state.qty}</div></div>
        <div class="sum-div"></div>
        <div class="sum-row"><div class="k">Face value (${state.qty} × ₹${state.denom})</div><div class="v">₹${face.toFixed(2)}</div></div>
        <div class="sum-row"><div class="k">MeeSeva service charge</div><div class="v">₹0.00</div></div>
        <div class="sum-row total"><div class="k">Grand total</div><div class="v">₹${face.toFixed(2)}</div></div>`;
      flowPrimary.textContent='Proceed to Pay';
      flowPrimary.disabled=false;
      flowPrimary.onclick=submitFlow;
    }
  }

  function wireScreen1(){
    const nameI=document.getElementById('nameInput');
    const qtyI=document.getElementById('qtyInput');
    const fName=document.getElementById('f-name');
    const fQty=document.getElementById('f-qty');
    nameI.addEventListener('input',e=>{state.name=e.target.value;validate1();});
    nameI.addEventListener('focus',()=>fName.classList.add('focus'));
    nameI.addEventListener('blur',()=>fName.classList.remove('focus'));
    qtyI.addEventListener('input',e=>{state.qty=e.target.value.replace(/[^0-9]/g,'');e.target.value=state.qty;updateTotalHint();validate1();});
    qtyI.addEventListener('focus',()=>fQty.classList.add('focus'));
    qtyI.addEventListener('blur',()=>fQty.classList.remove('focus'));
    document.querySelectorAll('.field.dropdown').forEach(f=>f.addEventListener('click',()=>openPicker(f.dataset.pick)));
    updateTotalHint();
  }
  function updateTotalHint(){
    const h=document.getElementById('totalHint');if(!h)return;
    const q=parseInt(state.qty,10);
    if(state.denom&&q>0){h.style.display='block';h.innerHTML='Grand total: <b>₹'+(q*state.denom).toFixed(2)+'</b>';}
    else{h.style.display='none';}
  }
  function validate1(){
    const q=parseInt(state.qty,10);
    const ok=state.name.trim()&&state.stampType&&state.denom&&q>0;
    flowPrimary.disabled=!ok;return ok;
  }

  // ---------- picker ----------
  let pickKind=null;
  function openPicker(kind){
    pickKind=kind;pickList.innerHTML='';
    pickTitle.textContent=kind==='type'?'Select stamp type':'Select denomination';
    if(kind==='type'){
      STAMP_TYPES.forEach(o=>{
        const it=document.createElement('div');it.className='pitem'+(o.t===state.stampType?' sel':'');
        it.innerHTML='<span>'+o.e+' '+o.t+'</span><span class="radio"></span>';
        it.addEventListener('click',()=>choosePick('type',o));
        pickList.appendChild(it);
      });
    } else {
      DENOMS.forEach(d=>{
        const it=document.createElement('div');it.className='pitem'+(state.denom===d?' sel':'');
        it.innerHTML='<span>₹'+d+'</span><span class="radio"></span>';
        it.addEventListener('click',()=>choosePick('denom',d));
        pickList.appendChild(it);
      });
    }
    pickScrim.classList.add('show');picker.classList.add('show');
  }
  function closePicker(){pickScrim.classList.remove('show');picker.classList.remove('show');}
  pickScrim.addEventListener('click',closePicker);
  function choosePick(kind,val){
    if(kind==='type'){state.stampType=val.t;state.stampEmoji=val.e;const v=document.getElementById('typeVal');v.textContent=val.e+' '+val.t;v.parentElement.classList.remove('ph');}
    else{state.denom=val;const v=document.getElementById('denomVal');v.textContent='₹'+val;v.parentElement.classList.remove('ph');}
    updateTotalHint();validate1();closePicker();
  }

  // ---------- submit -> echo -> pay ----------
  function submitFlow(){
    closeFlow();
    const face=(state.qty*state.denom).toFixed(2);
    const row=document.createElement('div');row.className='row out';
    row.innerHTML=`<div class="bubble echo">
      <div class="quote"><div class="qbar"></div>
        <div class="qtext"><div class="qname">MeeSeva Telangana</div><div class="qprev">Purchase of Registration Stamps · Buy your stamps, labels and adhesives</div></div>
        <img class="qthumb" src="${BANNER}"></div>
      <div class="meta"><span class="sent">Sent ✓</span><span class="time">${TIME}</span></div></div>`;
    chat.appendChild(row);scrollDown();
    setTimeout(openPay,700);
  }

  function openPay(){payAmt.textContent=(state.qty*state.denom).toFixed(0);renderPayMethod();pay.classList.add('show');}
  function closePay(){pay.classList.remove('show');paySpin.classList.remove('show');}
  function renderPayMethod(){
    payBody.innerHTML=`<h4>Payment Method</h4>
      <div class="pmethod sel"><div class="r"></div><span>UPI</span></div>
      <div class="pmethod"><div class="r"></div><span>Other Payment Modes</span></div>
      <div class="disc"><b>Disclaimer:</b><br>1. No refunds for successful transactions. If the transaction fails, payment gateway charges (if any) may not be refunded.</div>
      <div class="pactions"><a data-a="cancel">Cancel</a><a data-a="continue">Continue</a></div>`;
    payBody.querySelectorAll('.pmethod').forEach(m=>m.addEventListener('click',()=>{payBody.querySelectorAll('.pmethod').forEach(x=>x.classList.remove('sel'));m.classList.add('sel');}));
    payBody.querySelector('[data-a="cancel"]').addEventListener('click',closePay);
    payBody.querySelector('[data-a="continue"]').addEventListener('click',renderUpiApps);
  }
  function renderUpiApps(){
    const apps=[['Google Pay','<span style="color:#4285F4">G</span>'],['PhonePe','<span style="background:#5f259f;color:#fff;border-radius:50%;width:26px;height:26px;display:flex;align-items:center;justify-content:center;font-size:12px">पे</span>'],
      ['PayTm','<span style="color:#00baf2;font-size:10px">pay<span style="color:#002970">tm</span></span>'],['CRED','<span>◆</span>'],
      ['BHIM','<span style="color:#e67817">₹</span>'],['Kiwi','<span style="color:#7cb342;font-size:11px">kiwi</span>'],
      ['MobiKwik','<span style="color:#2a4bd7">Ⓜ</span>'],['Navi','<span style="color:#00b6a1;font-weight:900">N:</span>'],
      ['SuperMoney','<span style="background:#5b3df5;color:#fff;border-radius:6px;width:26px;height:26px;display:flex;align-items:center;justify-content:center">◈</span>']];
    let grid='';apps.forEach(a=>{grid+='<div class="app"><span class="g">'+a[1]+'</span>'+a[0]+'</div>';});
    payBody.innerHTML='<div class="upi-head"><span class="tag">UPI</span>Pay using UPI</div><div class="apps">'+grid+'</div>';
    payBody.querySelectorAll('.app').forEach(el=>el.addEventListener('click',completePayment));
  }
  function completePayment(){paySpin.classList.add('show');setTimeout(()=>{closePay();showSuccess();},1700);}

  function showSuccess(){
    botType(()=>{
      const total=(state.qty*state.denom).toFixed(2);
      const challan='<img class="challanimg" src="'+CHALLAN_IMG+'" alt="Challan">';
      const text=`✅ <b>Payment Successful!</b>

🎉 Thank you, ${state.name}! Your stamp purchase is confirmed.

👉 Next step: Collect your stamps from the SRO within 15 days, carrying this challan.

⚠️ If stamps aren't in stock during your visit, the SRO will issue them at a later date and inform you.

🔒 Non-refundable · Part utilization not accepted

📞 Need help? Toll-free 1800 425 1110`;
      inBubble(challan+text,[{label:'Download Challan',act:'download'},{label:'Main Menu',act:'menu'}]);
    },850);
  }

  function handleAct(a){
    if(a==='openService')showStampCard();
    else if(a==='openFlow')openFlow();
    else if(a==='download')showToast('Challan downloaded');
    else if(a==='menu')start();
  }

  document.getElementById('hAvatar').innerHTML='<img src="'+LOGO+'" alt="MeeSeva">';
  var _m=document.getElementById('mAvatar');if(_m)_m.style.background='url("'+LOGO+'") center/cover';
  start();
})();
